    const re=()=>{this.form(el);this.run(el)};
    $('#wasym',el).onchange=e=>{WA.sym=e.target.value;this.run(el)};$('#wamode',el).onclick=e=>{const b=e.target.closest('[data-m]');if(b){WA.mode=b.dataset.m;re()}};
