const gateGet=async p=>{const r=await fetch('https://api.gateio.ws/api/v4/futures/usdt'+p);if(!r.ok)throw new Error('Gate.io HTTP '+r.status);return r.json()};
const mpGet=async p=>{const r=await fetch('https://mempool.space/api'+p);if(!r.ok)throw new Error('mempool.space HTTP '+r.status);const t=await r.text();try{return JSON.parse(t)}catch(e){return t}};
