const ULCAT={insiders:'Team en adviseurs',privateSale:'Investeerders (private sale)',publicSale:'Publieke verkoop',airdrop:'Airdrop',farming:'Beloningen',noncirculating:'Treasury / reserve',liquidity:'Liquiditeit'};
function sectorStats(){return Object.entries(SECTORS).map(([name,L])=>{const A=L.map(s=>S.crypto.get(s)).filter(a=>a&&a.price!=null&&a.ch24!=null);if(!A.length)return null;const mean=a=>a.length?a.reduce((s,x)=>s+x,0)/a.length:null;
  const w7=A.filter(a=>a.m&&a.m.ch7!=null),w30=A.filter(a=>a.m&&a.m.ch30!=null);const srt=A.slice().sort((a,b)=>b.ch24-a.ch24);
  return {name,A,n:A.length,ch24:mean(A.map(a=>a.ch24)),ch7:mean(w7.map(a=>a.m.ch7)),ch30:mean(w30.map(a=>a.m.ch30)),up:A.filter(a=>a.ch24>0).length/A.length*100,vol:A.reduce((s,a)=>s+(a.volQ||0),0),best:srt[0],worst:srt[srt.length-1]}}).filter(Boolean).sort((a,b)=>b.ch24-a.ch24)}
function sectorIndex(st){const A=st.A.filter(a=>a.cd&&a.cd.length>=10);if(!A.length)return [];const days=A[0].cd.map(c=>c.t);
  return days.map((t,i)=>{const v=A.map(a=>{const c=a.cd.find(x=>Math.abs(x.t-t)<12*HOUR);return c?c.c/a.cd[0].c:null}).filter(x=>x!=null);return [t,v.length?(v.reduce((s,x)=>s+x,0)/v.length-1)*100:null]}).concat([[Date.now(),A.reduce((s,a)=>s+(a.price/a.cd[0].c),0)/A.length*100-100]])}
