    const mine=new Set([...S.watch,...Object.keys(PT.P?.holdings||{})]);const L=U.events.map((e,i)=>({...e,i,a:S.crypto.get(e.sym)})).map(e=>({...e,val:e.a&&e.a.price!=null?e.tokens*e.a.price:null,pctMax:e.max?e.tokens/e.max*100:null}))
