/* ---------- steun en weerstand in de CSA-grafiek ---------- */
function srLevels(d,price){if(!d||d.length<15)return {sup:[],res:[]};const H=d.map(c=>c.h),L=d.map(c=>c.l),k=2,piv=[];
  for(let i=k;i<d.length-k;i++){if(H.slice(i-k,i+k+1).every(x=>x<=H[i]))piv.push(H[i]);if(L.slice(i-k,i+k+1).every(x=>x>=L[i]))piv.push(L[i])}
  const cl=[];for(const p of piv.sort((a,b)=>a-b)){const c=cl.find(c=>Math.abs(c.v/p-1)<.012);if(c){c.v=(c.v*c.n+p)/(c.n+1);c.n++}else cl.push({v:p,n:1})}
  const sup=cl.filter(c=>c.v<price*.997).sort((a,b)=>b.v-a.v).slice(0,2),res=cl.filter(c=>c.v>price*1.003).sort((a,b)=>a.v-b.v).slice(0,2);return {sup,res}}
{const od=drawChart;drawChart=function(box,a,d){od(box,a,d);if(!d||d.length<15||a.price==null||LS.get('srOff',false))return;const cc=$('.cc',box);if(!cc)return;
  const mn=Math.min(...d.map(c=>c.l)),mx=Math.max(...d.map(c=>c.h)),pad=(mx-mn)*.08||1,lo=mn-pad,hi=mx+pad;const lv=srLevels(d,a.price);const y=v=>(hi-v)/(hi-lo)*100;
  cc.insertAdjacentHTML('beforeend',[...lv.res.map(c=>['res',c]),...lv.sup.map(c=>['sup',c])].filter(([,c])=>c.v>lo&&c.v<hi).map(([t,c])=>`<div class="srl ${t}" style="top:${y(c.v).toFixed(1)}%"><span>${t==='res'?'Weerstand':'Steun'} ${money(a,c.v)}${c.n>1?` · ${c.n}× geraakt`:''}</span></div>`).join(''))}}

